# DK HRH.  Hjørring - Hørby
#
let hh = path("d3.dk.hrh");

with detail = 3, railway = :first :pax :removed {
    # point.dk.Hjørring  dk.FFH

    with link = "line.dk.HRH" {
        let hjv = path("d3.dk.hrh.hjv");

        track(:ror:lor :casing,
                hh[:hjo.yh - 0.1dl, :hjo.yh] >> 1ms >> 1mt
            ..  hh[:hjo.xh, :hjo.xh + 0.1dl]
            ..  hh[:hjo.zh, :hjo.zh + 0.1dl]
        );
        track(:casing, hh[:hjo.zh, :hjo.zh + 1.91km]);
        line_label(:left:sw, hh[:hjo.zh + 1.9km] << 0.5mt, "HRH");
        track(hh[:hjo.zh + 1.89km, :fug - 0.49sw]);
    }

    with link = "point.dk.Fuglsig", railway = :station {
        track(hh[:fug - 0.5sw, :fug + 0.5sw]);
        marker(:left :de.hp, hh[:fug] << 0.5mt);
        slabel(:right, hh[:fug] << 0.5mt << 1sh + (1.3dt, 0dt),
            "Fuglsig"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:fug + 0.49sw, :ilb - 0.49sw]);
    }

    with link = "point.dk.Ilbro", railway = :station {
        track(hh[:ilb - 0.5sw, :ilb + 0.5sw]);
        marker(:right :de.bf, hh[:ilb] >> 0.5mt);
        slabel(:bottom, hh[:ilb] >> 0.5mt >> 1sh >> 0.3dt,
            "Ilbro"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:ilb + 0.49sw, :lor - 0.49sw]);
    }

    with link = "point.dk.Lørslev", railway = :station {
        track(hh[:lor - 0.5sw, :lor + 0.5sw]);
        marker(:left :de.bf, hh[:lor] << 0.5mt);
        slabel(:top, hh[:lor] << 0.5mt << 1sh + (0.5dt, -0.3dt),
            "Lørslev"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:lor + 0.49sw, :boj - 0.49sw]);
    }

    with link = "point.dk.Bøjholm", railway = :station {
        track(hh[:boj - 0.5sw, :boj + 0.5sw]);
        marker(:left :de.hp, hh[:boj] << 0.5mt);
        slabel(:right, hh[:boj] << 0.5mt << 1sh + (1.1dt, 0.9dt),
            "Bøjholm"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:boj + 0.49sw, :tar - 0.49sw]);
    }

    with link = "point.dk.Tårs", railway = :station {
        track(hh[:tar - 0.5sw, :tar + 0.5sw]);
        marker(:left :de.bf, hh[:tar] << 0.5mt);
        slabel(:right, hh[:tar] << 0.5mt << 1sh + (1.5dt, 1.3dt),
            "Tårs"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:tar + 0.49sw, :bjo - 0.49sw]);
    }

    with link = "point.dk.Bjørnstrup", railway = :station {
        track(hh[:bjo - 0.5sw, :bjo + 0.5sw]);
        marker(:right :de.hp, hh[:bjo] >> 0.5mt);
        slabel(:left, hh[:bjo] >> 0.5mt >> 1sh + (-1.2dt, 1.4dt),
            "Bjørnstrup"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:bjo + 0.49sw, :tra - 0.49sw]);
    }

    with link = "point.dk.Tranget", railway = :station {
        track(hh[:tra - 0.5sw, :tra + 0.5sw]);
        marker(:right :de.bf, hh[:tra] >> 0.5mt);
        slabel(:bottom, hh[:tra] >> 0.5mt >> 1sh + (-0.3dt, 0.3dt),
            "Tranget"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:tra + 0.49sw, :sas - 0.49sw]);
    }

    with link = "point.dk.Sæsing", railway = :station {
        track(hh[:sas - 0.5sw, :sas + 0.5sw]);
        marker(:left :de.bf, hh[:sas] << 0.5mt);
        slabel(:top, hh[:sas] << 0.5mt << 1sh + (1dt, -0.4dt),
            "Sæsing"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:sas + 0.49sw, :sas + 0.91km]);
        line_label(:left:sw, hh[:sas + 0.9km] << 0.5mt, "HRH");
        track(hh[:sas + 0.89km, :dal - 0.49sw]);
    }

    with link = "point.dk.Dalvang", railway = :station {
        track(hh[:dal - 0.5sw, :dal + 0.5sw]);
        marker(:right :de.hp, hh[:dal] >> 0.5mt);
        slabel(:left, hh[:dal] >> 0.5mt >> 1sh + (-1.2dt, 1.4dt),
            "Dalvang"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:dal + 0.49sw, :ost.yv - 0.49seg]);
    }

    with link = "point.dk.Østervrå", railway = :station {
        track(hh[:ost.yv - 0.5seg, :ost + 0.5sw + 2dl]);
        track(
                hh[:ost.yv, :ost + 0.5sw] >> 1ms >> 1mt
            --  hh[:ost + 0.5sw + 1dl, :ost + 0.5sw + 1.1dl]
        );
        marker(:right :de.bf, hh[:ost] >> 1ms >> 1.5mt);
        slabel(:bottom :bold, hh[:ost] >> 1ms >> 1.5mt >> 1sh + (2dt, 0.7dt),
            "Østervrå"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:ost + 0.49sw + 2dl, :lin - 0.49sw]);
    }

    with link = "point.dk.Lindholm-Nordjylland", railway = :station {
        track(hh[:lin - 0.5sw, :lin + 0.5sw]);
        marker(:left :de.hp, hh[:lin] << 0.5mt);
        slabel(:top, hh[:lin] << 0.5mt << 1sh + (1dt, -0.3dt),
            "Lindholm"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:lin + 0.49sw, :tho - 0.49sw]);
    }

    with link = "point.dk.Thorshøj", railway = :station {
        track(hh[:tho - 0.5sw, :tho + 0.5sw]);
        marker(:right :de.bf, hh[:tho] >> 0.5mt);
        slabel(:left, hh[:tho] >> 0.5mt >> 1sh + (-1.5dt, 1.3dt),
            "Thorshøj"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:tho + 0.49sw, :tho + 1.21km]);
        line_label(:left:sw, hh[:tho + 1.2km] << 0.5mt, "HRH");
        track(hh[:tho + 1.19km, :tam - 0.49sw]);
    }

    with link = "point.dk.Tamstrup", railway = :station {
        track(hh[:tam - 0.5sw, :tam + 0.5sw]);
        marker(:right :de.hp, hh[:tam] >> 0.5mt);
        slabel(:left, hh[:tam] >> 0.5mt >> 1sh + (-1.7dt, 1.5dt),
            "Tamstrup"
        );
    }

    with link = "line.dk.HRH" {
        track(hh[:tam + 0.49sw, :hor.zb]);
        track(:lor,
                hh[:hor.zb - 0.1dl, :hor.zb]
            ..  hh[:hor.yb, :hor.yb + 0.1dl] >> 1ms >> 1mt
        );
    }

    # point.dk.Hørby  dk.NFH
}

